import logging
import queue
import threading

log = logging.getLogger(__name__)


class _Shutdown:
    """Sentinel type so a bare object() can never be confused with a real item."""

    def __repr__(self):
        return "<shutdown>"


SHUTDOWN = _Shutdown()


class QueueWorker:
    """Drains a queue.Queue on a background thread, handing each item to a callback."""

    def __init__(self, callback, q=None, name="queue-worker"):
        self.callback = callback
        self.queue = q if q is not None else queue.Queue()
        self._thread = threading.Thread(target=self._run, name=name, daemon=True)
        self._started = False
        self._stopped = threading.Event()

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def submit(self, item):
        if self._stopped.is_set():
            raise RuntimeError("worker is shutting down")
        self.queue.put(item)

    def _run(self):
        while True:
            item = self.queue.get()
            try:
                if item is SHUTDOWN:
                    return
                self.callback(item)
            except Exception:
                # One bad item must not kill the thread; the queue keeps draining.
                log.exception("callback failed for item %r", item)
            finally:
                self.queue.task_done()

    def join_queue(self):
        self.queue.join()

    def stop(self, timeout=None, drain=True):
        """Queue the sentinel and wait for the thread to reach it.

        Items already queued are processed first, since the sentinel sits behind
        them in FIFO order. drain=False skips waiting on the queue itself and
        only bounds the thread join.
        """
        if not self._started or self._stopped.is_set():
            return
        self._stopped.set()
        self.queue.put(SHUTDOWN)
        if drain:
            self.queue.join()
        self._thread.join(timeout)
        if self._thread.is_alive():
            log.warning("worker thread did not exit within %s seconds", timeout)

    def __enter__(self):
        return self.start()

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
